// REQUEST VALIDATION & SANITIZATION
const query = $input.item.json.query || '';
const practiceId = $input.item.json.practiceId || '';

// Security: Validate practice ID format
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
if (!practiceId || !uuidRegex.test(practiceId)) {
  throw new Error('Invalid or missing practice ID - potential security breach');
}

// Security: Query length limit
if (query.length > 500) {
  throw new Error('Query too long - maximum 500 characters');
}

// Security: Remove dangerous characters
const cleanQuery = query
  .replace(/[;'"\\]/g, '') // Remove SQL injection characters
  .replace(/\b(DROP|DELETE|UPDATE|INSERT|CREATE|ALTER|GRANT|REVOKE)\b/gi, '') // Remove DDL/DML
  .toLowerCase()
  .trim();

// Extract medical context for better SQL generation
const medicalContext = {
  hasAge: /\b(\d+)\s*(year|yr)s?\s*(old)?\b/i.test(query),
  hasGender: /\b(male|female|men|women)\b/i.test(query),
  hasMedicalAid: /\b(medical aid|insurance|coverage)\b/i.test(query),
  hasCondition: /\b(diabetes|hypertension|asthma|covid|cancer|heart)\b/i.test(query),
  hasTimeframe: /\b(last|recent|today|yesterday|month|week|year)\b/i.test(query),
  hasBranch: /\b(branch|location|clinic|site)\b/i.test(query)
};

// Log for audit
console.log('Query received:', {
  originalLength: query.length,
  cleanedLength: cleanQuery.length,
  practiceId: practiceId,
  medicalContext: medicalContext
});

return {
  originalQuery: query,
  cleanQuery: cleanQuery,
  medicalContext: medicalContext,
  practiceId: practiceId,
  timestamp: new Date().toISOString(),
  requestId: crypto.randomUUID()
};

// Format schema for AI consumption
const schemaRows = $input.all();
let schemaText = 'HEALTHCARE DATABASE SCHEMA:\n\n';
let currentTable = '';
let relationships = [];

for (const row of schemaRows) {
  const { table_name, column_name, data_type, is_nullable, constraint_type } = row.json;

  if (table_name !== currentTable) {
    if (currentTable) schemaText += '\n';
    schemaText += `TABLE: ${table_name}\n`;
    currentTable = table_name;
  }

  const nullable = is_nullable === 'YES' ? 'NULL' : 'NOT NULL';
  const constraint = constraint_type ? ` [${constraint_type}]` : '';
  schemaText += `  - ${column_name} (${data_type}, ${nullable})${constraint}\n`;

  // Track foreign keys for relationships
  if (constraint_type === 'FK' && column_name.endsWith('_id')) {
    const referencedTable = column_name.replace('_id', 's');
    relationships.push(`${table_name}.${column_name} -> ${referencedTable}.id`);
  }
}

// Add relationship information
schemaText += `\nKEY RELATIONSHIPS:\n`;
schemaText += `- patients.id -> visits.patient_id (one-to-many)\n`;
schemaText += `- patients.id -> medical_aid_details.patient_id (one-to-many)\n`;
schemaText += `- patients.id -> appointments.patient_id (one-to-many)\n`;
schemaText += `- patients.branch_id -> branches.id (many-to-one)\n`;
schemaText += `- visits.id -> medical_records.visit_id (one-to-one)\n`;
schemaText += `- branches.practice_id -> practices.id (many-to-one)\n`;

// Add important notes
schemaText += `\nIMPORTANT QUERY RULES:\n`;
schemaText += `- Age calculation: EXTRACT(YEAR FROM AGE(patients.date_of_birth))\n`;
schemaText += `- Always filter by practice_id for multi-tenant isolation\n`;
schemaText += `- Use ILIKE for case-insensitive text search\n`;
schemaText += `- Date ranges: created_at >= CURRENT_DATE - INTERVAL '30 days'\n`;

const queryContext = $('Validate & Clean Query').item.json;

return {
  schema: schemaText,
  query: queryContext.cleanQuery,
  originalQuery: queryContext.originalQuery,
  practiceId: queryContext.practiceId,
  medicalContext: queryContext.medicalContext,
  requestId: queryContext.requestId
};

// Parse OpenAI response and validate
try {
  const aiResponse = $input.item.json.output;

  // Extract JSON from response
  let jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
  if (!jsonMatch) {
    throw new Error('No valid JSON found in OpenAI response');
  }

  const parsed = JSON.parse(jsonMatch[0]);

  // Validate required fields
  if (!parsed.sql || !parsed.description) {
    throw new Error('Missing required fields in AI response');
  }

  // Replace PRACTICE_ID placeholder
  const practiceId = $('Validate & Clean Query').item.json.practiceId;
  parsed.sql = parsed.sql.replace(/PRACTICE_ID/g, practiceId);

  // Basic SQL validation
  const sqlUpper = parsed.sql.toUpperCase();
  if (!sqlUpper.includes('SELECT DISTINCT PATIENTS.ID')) {
    throw new Error('SQL must select DISTINCT patients.id');
  }

  if (!sqlUpper.includes('WHERE')) {
    throw new Error('SQL must have WHERE clause');
  }

  if (!parsed.sql.includes(practiceId)) {
    throw new Error('SQL must filter by practice_id');
  }

  // Add metadata
  parsed.generatedAt = new Date().toISOString();
  parsed.requestId = $('Validate & Clean Query').item.json.requestId;
  parsed.originalQuery = $('Validate & Clean Query').item.json.originalQuery;

  return parsed;

} catch (error) {
  return {
    error: true,
    message: 'Failed to generate valid SQL: ' + error.message,
    rawResponse: $input.item.json.output,
    requestId: $('Validate & Clean Query').item.json.requestId
  };
}

// Parse xAI verification response
try {
  const xaiResponse = $input.item.json;
  const sqlData = $('Parse & Validate OpenAI Response').item.json;

  // Extract verification result
  let verificationResult;
  if (xaiResponse.choices && xaiResponse.choices[0]) {
    const content = xaiResponse.choices[0].message.content;
    verificationResult = JSON.parse(content);
  } else {
    throw new Error('Invalid xAI response format');
  }

  // Default structure if xAI doesn't return expected format
  const verification = {
    verified: verificationResult.verified !== false,
    risk_level: verificationResult.risk_level || 'medium',
    issues: verificationResult.issues || [],
    security_score: verificationResult.security_score || 0.5,
    recommendations: verificationResult.recommendations || []
  };

  // Additional security checks
  const sql = sqlData.sql.toUpperCase();

  // Check for dangerous operations
  const dangerousPatterns = [
    /\bDROP\b/, /\bDELETE\b/, /\bUPDATE\b/, /\bINSERT\b/,
    /\bCREATE\b/, /\bALTER\b/, /\bGRANT\b/, /\bREVOKE\b/,
    /\bEXEC\b/, /\bEXECUTE\b/, /;/, /--/, /\/\*/
  ];

  for (const pattern of dangerousPatterns) {
    if (pattern.test(sql)) {
      verification.verified = false;
      verification.risk_level = 'critical';
      verification.issues.push(`Dangerous pattern detected: ${pattern}`);
    }
  }

  // Check for practice_id
  if (!sqlData.sql.includes(sqlData.practiceId)) {
    verification.verified = false;
    verification.risk_level = 'high';
    verification.issues.push('Missing practice_id filter - data leak risk');
  }

  // Combine results
  return {
    sql: verification.verified ? sqlData.sql : null,
    description: sqlData.description,
    verified: verification.verified,
    risk_level: verification.risk_level,
    issues: verification.issues,
    confidence: sqlData.confidence,
    security_score: verification.security_score,
    requestId: sqlData.requestId,
    verifiedAt: new Date().toISOString()
  };

} catch (error) {
  return {
    error: true,
    message: 'Security verification failed: ' + error.message,
    verified: false,
    risk_level: 'critical'
  };
}

// Format successful response
const queryResults = $input.all();
const patientIds = queryResults.map(row => row.json.id).filter(id => id);
const verification = $('Parse Security Verification').item.json;
const originalRequest = $('Validate & Clean Query').item.json;

// Log successful query for analytics
const auditLog = {
  requestId: originalRequest.requestId,
  practiceId: originalRequest.practiceId,
  query: originalRequest.originalQuery,
  resultCount: patientIds.length,
  executionTime: Date.now() - new Date(originalRequest.timestamp).getTime(),
  success: true
};

console.log('Query executed successfully:', auditLog);

return {
  success: true,
  patientIds: patientIds,
  count: patientIds.length,
  description: verification.description,
  searchQuery: originalRequest.originalQuery,
  confidence: verification.confidence,
  securityScore: verification.security_score,
  timestamp: new Date().toISOString(),
  requestId: originalRequest.requestId
};

// Format error response with details
const error = $input.item.json;
const originalRequest = $('Validate & Clean Query').first().json;

// Determine error type and user message
let userMessage = 'Unable to process your search. Please try a simpler query.';
let errorType = 'unknown';

if (error.risk_level === 'critical') {
  userMessage = 'Security check failed. Please contact support.';
  errorType = 'security';
} else if (error.message?.includes('practice_id')) {
  userMessage = 'Authentication error. Please log in again.';
  errorType = 'auth';
} else if (error.message?.includes('SQL')) {
  userMessage = 'Could not understand your search. Try: "women over 50" or "patients with diabetes"';
  errorType = 'parsing';
}

// Log error for monitoring
const errorLog = {
  requestId: originalRequest?.requestId || 'unknown',
  practiceId: originalRequest?.practiceId || 'unknown',
  query: originalRequest?.originalQuery || 'unknown',
  errorType: errorType,
  errorDetails: error,
  timestamp: new Date().toISOString()
};

console.error('Query failed:', errorLog);

return {
  success: false,
  error: userMessage,
  errorType: errorType,
  details: process.env.NODE_ENV === 'development' ? error : undefined,
  requestId: originalRequest?.requestId,
  timestamp: new Date().toISOString()
};
